// ==================== the whispering (v77) ====================
// A recording of creepy whispering (freesound community, "creepy whispering 6690"; also in assets/sfx/whisper_source.mp3).
// Used for every whisper in Part One and Part Two: each one plays a different stretch of it, at a slightly different
// speed, panned to one side, so it doesn't sound like the same clip every time.
const WHISPER = { b64: '', buf: null, busy: false, last: 0 };
function whisperBuf() {
  if (WHISPER.buf || WHISPER.busy || typeof AC == 'undefined' || !AC) return WHISPER.buf; WHISPER.busy = true;
  const t = atob(WHISPER.b64), u8 = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u8[i] = t.charCodeAt(i);
  AC.decodeAudioData(u8.buffer, b => { WHISPER.buf = b }, () => { WHISPER.busy = false });
  return null;
}
// vol: 0..1 before the sound setting; dur: seconds of it to play; pan: -1 left .. 1 right (random if left out)
function playWhisper(vol = .3, dur = 1.8, pan) {
  if (typeof AC == 'undefined' || !AC) return false; const b = whisperBuf(); if (!b) return false;
  const t = AC.currentTime + .01, L = Math.min(dur, b.duration - .1), off = Math.random() * Math.max(0, b.duration - L), rate = .88 + Math.random() * .2;
  const s = AC.createBufferSource(), g = AC.createGain(); s.buffer = b; s.playbackRate.value = rate;
  const v = vol * (typeof opt != 'undefined' ? opt.s / 10 : .7); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(v, t + .25); g.gain.setValueAtTime(v, t + Math.max(.3, L / rate - .4)); g.gain.linearRampToValueAtTime(0, t + L / rate);
  let out = g; if (AC.createStereoPanner) { const p = AC.createStereoPanner(); p.pan.value = Math.max(-1, Math.min(1, pan ?? (Math.random() - .5) * 1.8)); g.connect(p); p.connect(AC.destination) } else g.connect(AC.destination);
  s.connect(g); s.start(t, off, L + .05); WHISPER.last = performance.now(); return true;
}
// Part One: the fear places whisper at you while you walk through them, now and then, from one side or the other
setInterval(() => {
  if (typeof AC == 'undefined' || !AC || document.hidden) return; whisperBuf();
  if (typeof sc != 'undefined' && sc == 'fear' && typeof FS != 'undefined' && FS && performance.now() - WHISPER.last > 5000 + Math.random() * 6000) playWhisper(.35, 1.6 + Math.random() * 1.4);
}, 500);
